    if current == nil then
        ns.data.items[id] = record
    elseif type(current) == "table" and
           (current.name == nil or current.name == record.en) and
           (current.en == nil or current.en == record.en) then
        current.en = current.en or record.en
        current.name = record.name
    end
end
